/* @autogenerated */
package net.civeira.phylax.bootstrap.install;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import net.civeira.phylax.common.infrastructure.config.IsolatedConfig;
import net.civeira.phylax.common.infrastructure.config.IsolatedConfigLoaderTestSupport;

class OidcSeedConfigUnitTest {
  private static final String SEED = LocalSeed.PATH;
  private static final List<String> SECRETS =
      List.of("oidc.root.password", "oidc.relying-party.api-key", "oidc.trusted-client.secret",
          "oidc.api-keys.collector", "oidc.api-keys.sync");

  @TempDir
  Path external;

  @Test
  void testSecretsAreMissingOutsideDev() {
    IsolatedConfig config = load(List.of("prod"), Map.of());

    assertTrue(config.exists());
    SECRETS.forEach(key -> assertEquals(Optional.empty(), config.getConfig(key), key));
    assertEquals("main", config.getRequiredConfig("oidc.tenant.name"));
    assertEquals("ROOT", config.getRequiredConfig("oidc.root.name"));
    assertEquals(Boolean.TRUE,
        config.getRequiredConfig("oidc.root.temporal-password", Boolean.class));
  }

  @Test
  void testTheExternalFileProvidesTheLocalValues() {
    LocalSeed.install(external);
    IsolatedConfig config = load(List.of("prod"), Map.of());

    SECRETS.forEach(key -> assertTrue(config.getConfig(key).isPresent(), key));
    assertEquals(Boolean.FALSE,
        config.getRequiredConfig("oidc.root.temporal-password", Boolean.class));
    assertEquals("http://localhost:4200/*",
        config.getRequiredConfig("oidc.trusted-client.redirect"));
  }

  @Test
  void testEnvironmentProvidesTheSecrets() {
    IsolatedConfig config = load(List.of("prod"), Map.of("OIDC_ROOT_PASSWORD", "from-env"));

    assertEquals(Optional.of("from-env"), config.getConfig("oidc.root.password"));
  }

  private IsolatedConfig load(List<String> profiles, Map<String, String> environment) {
    return IsolatedConfigLoaderTestSupport.loader(external, profiles, environment).load(SEED);
  }
}
